import * as yup from "yup";

export const createBalanceSchema = yup.object({
  name: yup.string().required("The name field is required."),
  persian_name: yup.string().required("The persian_name field is required."),
  value: yup.string().required("The value field is required."),
  type: yup.object().required("The type field is required."),
  timeframe: yup.object().required("The timeframe field is required."),
});

export const createRateSchema = yup.object({
  Name: yup.string().required("The Name field is required."),
  persian_name: yup.string().required("The persian_name field is required."),
  category: yup.object().required("The category field is required."),
  source_mcc: yup.string().required("The source_mcc field is required."),
  source_mnc: yup.string().required("The source_mnc field is required."),
  destination_mcc: yup
    .string()
    .required("The destination_mcc field is required."),
  destination_mnc: yup
    .string()
    .required("The destination_mnc field is required."),
  per: yup.string().required("The per field is required."),
  monetary_unit: yup.string().required("The monetary_unit field is required."),
  non_monetary_unit: yup
    .string()
    .required("The non_monetary_unit field is required."),
});
export const updateRateSchema = yup.object({
  monetary_unit: yup.string().required("The monetary_unit field is required."),
  non_monetary_unit: yup
    .string()
    .required("The non_monetary_unit field is required."),
});

