import { useState } from "react";
import useHttp from "./use_http";
import { useFormik } from "formik";
import { createAccountSchema } from "../utility/schemas";
import toast from "react-hot-toast";
import { useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import {
  setAddBalanceModal,
  setDebitModal,
  setDeleteModal,
  setInfoModal,
  setRemoveBalanceModal,
  setSelectedAccount,
  setTopupModal,
  setUpdateBalanceModal,
  setViewAccountData,
} from "../redux/account_slice";
import moment from "moment/moment";

const useAccount = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const { httpService } = useHttp();

  const [accountLoadings, setAccountLoadings] = useState({
    getAccounts: false,
    createAccount: false,
    patchAccount: false,
    deleteAccount: false,
    getAccountById: false,
    getBalances: false,
    addBalance: false,
    removeBalance: false,
    getAccountUsageHourly: false,
    getAccountUsageDaily: false,
    updateBalance: false,
    topupBalance: false,
    debitBalance: false,
  });
  const [accountPaginates, setAccountPaginates] = useState({
    current: 1,
    total: 1,
    per_page: 10,
  });

  const [filters, setFilters] = useState({
    imsi: "",
    msisdn: "",
    permanent: null,
  });

  const [accountList, setAccountList] = useState([]);
  const [balanceList, setBalanceList] = useState([]);
  const [accountUsageData, setAccountUsageData] = useState({
    categories: [],
    data: [],
  });

  const [selectedBalance, setSelectedBalance] = useState(null);
  const [selectedAccountBalance, setSelectedAccountBalance] = useState(null);

  const viewAccountData = useSelector(
    (state) => state.accounts.viewAccountData
  );

  const getAccounts = async (page, filtersData) => {
    const paramsData = {
      page: page,
    };
    if (filtersData?.imsi?.length > 0) {
      paramsData["imsi"] = filtersData?.imsi;
    }
    if (filtersData?.msisdn?.length > 0) {
      paramsData["msisdn"] = filtersData?.msisdn;
    }
    if (filtersData?.permanent) {
      paramsData["permanent"] = filtersData?.permanent?.value;
    }
    try {
      setAccountLoadings({ ...accountLoadings, getAccounts: true });
      const response = await httpService.get(`/v1/accounts`, {
        params: paramsData,
      });
      setAccountLoadings({ ...accountLoadings, getAccounts: false });
      setAccountPaginates({
        ...accountPaginates,
        current: response.data.meta.page,
        total: response.data.meta.pages,
        per_page: response.data.meta.limit,
      });
      if (response.data.data) {
        setAccountList(response.data.data);
      } else {
        setAccountList([]);
      }
    } catch ({ err, response }) {
      setAccountLoadings({ ...accountLoadings, getAccounts: false });
    }
  };

  const createAccountController = useFormik({
    initialValues: {
      imsi: "",
      msisdn: "",
      permanent: false,
    },
    validationSchema: createAccountSchema,
    onSubmit: (values) => {
      createAccount(values);
    },
  });

  const createAccount = async (values) => {
    let postData = {
      imsi: values.imsi,
      msisdn: values.msisdn,
      permanent: values.permanent,
    };
    try {
      setAccountLoadings({ ...accountLoadings, createAccount: true });
      const response = await httpService.post(`/v1/accounts`, postData);
      setAccountLoadings({ ...accountLoadings, createAccount: false });
      if (response.status == 200 || response.status == 201) {
        toast.success("Account created successfully");
        navigate("/accounts/all");
      } else {
        toast.error(response.data.data);
      }
    } catch ({ err, response }) {
      setAccountLoadings({ ...accountLoadings, createAccount: false });
    }
  };

  const deleteAccount = async (account_imsi) => {
    try {
      setAccountLoadings({ ...accountLoadings, deleteAccount: true });
      const response = await httpService.delete(`/v1/accounts/${account_imsi}`);
      if (response.status === 200 || response.status == 201) {
        setAccountLoadings({ ...accountLoadings, deleteAccount: false });
        toast.success("Account deleted successfully.");
        dispatch(setDeleteModal(null));
        dispatch(setSelectedAccount(null));
        setAccountPaginates({ ...accountPaginates, current: 1 });
        getAccounts(1);
      } else {
        toast.error(response.data.data);
      }
    } catch ({ err, response }) {
      setAccountLoadings({ ...accountLoadings, deleteAccount: false });
    }
  };

  const patchAccount = async (account) => {
    let postData = {
      current_status: account.Permanent,
    };
    if (account.Permanent == true) {
      postData["default_balance_id"] = account.Balances?.find(
        (balance) => balance.balance_name == "permanent_default_monetary"
      ).id;
    } else {
      postData["default_balance_id"] = account.Balances?.find(
        (balance) => balance.balance_name == "credit_default_monetary"
      ).id;
    }
    try {
      setAccountLoadings({ ...accountLoadings, patchAccount: true });
      const response = await httpService.patch(
        `/v1/accounts/toggle/${account.IMSI}`,
        postData
      );
      setAccountLoadings({ ...accountLoadings, patchAccount: false });
      if (response.status == 200 || response.status == 201) {
        toast.success("Account status updated successfully.");
        getAccountById(account.IMSI);
        getAccounts(accountPaginates.current, filters);
      } else {
        toast.error(response.data.data);
      }
    } catch ({ err, response }) {
      setAccountLoadings({ ...accountLoadings, patchAccount: false });
    }
  };

  const getAccountById = async (account_imsi) => {
    try {
      setAccountLoadings({ ...accountLoadings, getAccountById: true });
      const response = await httpService.get(`/v1/accounts/${account_imsi}`);
      setAccountLoadings({ ...accountLoadings, getAccountById: false });
      if (response.status == 200 || response.status == 201) {
        dispatch(setViewAccountData(response.data.data));
      } else {
        dispatch(setInfoModal(null));
        dispatch(setSelectedAccount(null));
        toast.error(response.data.data);
      }
    } catch ({ err, response }) {
      setAccountLoadings({ ...accountLoadings, getAccountById: false });
    }
  };

  const getBalances = async () => {
    let array = [];
    try {
      setAccountLoadings({ ...accountLoadings, getBalances: true });
      const response = await httpService.get(`/v1/balances`);
      setAccountLoadings({ ...accountLoadings, getBalances: false });
      if (response.data.data) {
        response.data.data
          .filter((o) => o.Type !== "monetary")
          .map((item) => {
            array.push({
              label: item.Name,
              value: item.Name,
            });
          });
        setBalanceList(array);
      } else {
        setBalanceList([]);
      }
    } catch ({ err, response }) {
      setAccountLoadings({ ...accountLoadings, getBalances: false });
    }
  };

  const addBalance = async () => {
    if (!selectedBalance) {
      toast.error("Please select a balance.");
    } else {
      try {
        setAccountLoadings({ ...accountLoadings, addBalance: true });
        const response = await httpService.post(
          `/v1/accountbalances/${viewAccountData.IMSI}`,
          {
            balance_name: selectedBalance?.value,
          }
        );
        setAccountLoadings({ ...accountLoadings, addBalance: false });
        if (response.status == 200 || response.status == 201) {
          getAccountById(viewAccountData?.IMSI);
          toast.success("Balance added successfully.");
          dispatch(setAddBalanceModal(null));
        }
      } catch ({ err, response }) {
        setAccountLoadings({ ...accountLoadings, addBalance: false });
      }
    }
  };

  const removeBalance = async () => {
    try {
      setAccountLoadings({ ...accountLoadings, removeBalance: true });
      const response = await httpService.delete(`/v1/accountbalances`, {
        data: {
          account_balance_id: selectedAccountBalance?.id,
        },
      });
      setAccountLoadings({ ...accountLoadings, removeBalance: false });
      if (response.status == 200 || response.status == 201) {
        dispatch(setRemoveBalanceModal(null));
        toast.success("Balance removed successfully.");
        getAccountById(viewAccountData?.IMSI);
      } else {
        toast.error(response.data.data);
      }
    } catch ({ err, response }) {
      setAccountLoadings({ ...accountLoadings, removeBalance: false });
    }
  };

  const getAccountUsageHourly = async (start_time, category, account_imsi) => {
    let convertedDate = `${start_time.year}-${
      start_time.month < 10 ? "0" + start_time.month : start_time.month
    }-${start_time.day < 10 ? "0" + start_time.day : start_time.day}`;

    let insideStartTime;
    if (moment(convertedDate).isSame(moment(), "day")) {
      insideStartTime = moment(convertedDate, "YYYY-MM-DD")
        .set({
          hour: moment().hour(),
          minute: moment().minute(),
          second: moment().second(),
        })
        .utc()
        .format();
    } else {
      insideStartTime = `${convertedDate}T23:59:59Z`;
    }
    let insideCategory = category.value;
    let categoriesArray = [];
    let dataArray = [];
    try {
      setAccountLoadings({ ...accountLoadings, getAccountUsageHourly: true });
      const response = await httpService.post(
        `/v1/cdrs/hourly?start_time=${insideStartTime}`,
        {
          imsi: account_imsi,
          category: insideCategory,
        }
      );
      setAccountLoadings({ ...accountLoadings, getAccountUsageHourly: false });
      if (response.data.data) {
        response.data.data.map((item) => {
          categoriesArray.push(item.hour);
          dataArray.push(item.total_usage);
        });
        setAccountUsageData({
          categories: categoriesArray,
          data: dataArray,
        });
      }
    } catch ({ err, response }) {
      setAccountLoadings({ ...accountLoadings, getAccountUsageHourly: false });
    }
  };

  const getAccountUsageDaily = async (start_time, category, account_imsi) => {
    let convertedDate = `${start_time.year}-${
      start_time.month < 10 ? "0" + start_time.month : start_time.month
    }-${start_time.day < 10 ? "0" + start_time.day : start_time.day}`;

    let insideStartTime;
    if (moment(convertedDate).isSame(moment(), "day")) {
      insideStartTime = moment(convertedDate, "YYYY-MM-DD")
        .set({
          hour: moment().hour(),
          minute: moment().minute(),
          second: moment().second(),
        })
        .utc()
        .format();
    } else {
      insideStartTime = `${convertedDate}T23:59:59Z`;
    }
    let insideCategory = category.value;
    let categoriesArray = [];
    let dataArray = [];
    try {
      setAccountLoadings({ ...accountLoadings, getAccountUsageDaily: true });
      const response = await httpService.post(
        `/v1/cdrs/daily?start_time=${insideStartTime}`,
        {
          imsi: account_imsi,
          category: insideCategory,
        }
      );
      setAccountLoadings({ ...accountLoadings, getAccountUsageDaily: false });
      if (response.data.data) {
        response.data.data.map((item) => {
          categoriesArray.push(item.day);
          dataArray.push(item.total_usage);
        });
        setAccountUsageData({
          categories: categoriesArray,
          data: dataArray,
        });
      }
    } catch ({ err, response }) {
      setAccountLoadings({ ...accountLoadings, getAccountUsageDaily: false });
    }
  };

  const updateBalance = async (data, balance) => {
    let postData = {
      account_balance_id: balance.id,
    };
    // data
    if (balance.type == "data") {
      if (data.unit.value == "GB") {
        postData["amount"] = data.value * 1024 * 1024 * 1024;
      }
      if (data.unit.value == "MB") {
        postData["amount"] = data.value * 1024 * 1024;
      }
      if (data.unit.value == "KB") {
        postData["amount"] = data.value * 1024;
      }
    }
    // voice and video
    let inisdeHours = data.hours;
    let insideMinutes = data.minutes;
    if (balance.type == "voice" || balance.type == "video") {
      if (data.hours.length === 0) {
        inisdeHours = 0;
      }
      if (data.minutes.length === 0) {
        insideMinutes = 0;
      }
      if (parseFloat(inisdeHours) == 0 && parseFloat(insideMinutes) == 0) {
        toast.error("Please enter hours or minutes");
      } else if (parseFloat(insideMinutes) > 59) {
        toast.error("Minutes can't be more than 59");
      } else {
        postData["amount"] = inisdeHours * 60 * 60 + insideMinutes * 60;
      }
    }
    // monetary
    if (balance.type == "monetary") {
      if (data.length === 0) {
        toast.error("Please enter amount");
      } else {
        postData["amount"] = parseFloat(data);
      }
    }
    if (postData.amount || postData.amount == 0) {
      try {
        setAccountLoadings({ ...accountLoadings, updateBalance: true });
        const response = await httpService.patch(
          `/v1/accountbalances/update`,
          postData
        );
        setAccountLoadings({ ...accountLoadings, updateBalance: false });
        if (response.status == 200 || response.status == 201) {
          toast.success("Balance value updated successfully.");
          dispatch(setUpdateBalanceModal(null));
          getAccountById(viewAccountData?.IMSI);
        }
      } catch ({ err, response }) {
        setAccountLoadings({ ...accountLoadings, updateBalance: false });
      }
    }
  };

  const topupBalance = async (data, balance) => {
    let postData = {
      account_balance_id: balance.id,
    };
    // data
    if (balance.type == "data") {
      if (data.unit.value == "GB") {
        postData["amount"] = data.value * 1024 * 1024 * 1024;
      }
      if (data.unit.value == "MB") {
        postData["amount"] = data.value * 1024 * 1024;
      }
      if (data.unit.value == "KB") {
        postData["amount"] = data.value * 1024;
      }
    }
    // voice and video
    let inisdeHours = data.hours;
    let insideMinutes = data.minutes;
    if (balance.type == "voice" || balance.type == "video") {
      if (data.hours.length === 0) {
        inisdeHours = 0;
      }
      if (data.minutes.length === 0) {
        insideMinutes = 0;
      }
      if (parseFloat(inisdeHours) == 0 && parseFloat(insideMinutes) == 0) {
        toast.error("Please enter hours or minutes");
      } else if (parseFloat(insideMinutes) > 59) {
        toast.error("Minutes can't be more than 59");
      } else {
        postData["amount"] = inisdeHours * 60 * 60 + insideMinutes * 60;
      }
    }
    // monetary
    if (balance.type == "monetary") {
      if (data.length === 0) {
        toast.error("Please enter amount");
      } else {
        postData["amount"] = parseFloat(data);
      }
    }
    if (postData.amount) {
      try {
        setAccountLoadings({ ...accountLoadings, topupBalance: true });
        const response = await httpService.patch(
          `/v1/accountbalances/topup`,
          postData
        );
        setAccountLoadings({ ...accountLoadings, topupBalance: false });
        if (response.status == 200 || response.status == 201) {
          toast.success("Balance topuped successfully.");
          dispatch(setTopupModal(null));
          getAccountById(viewAccountData?.IMSI);
        }
      } catch ({ err, response }) {
        setAccountLoadings({ ...accountLoadings, topupBalance: false });
      }
    }
  };

  const debitBalance = async (data, balance) => {
    let postData = {
      account_balance_id: balance.id,
    };
    // data
    if (balance.type == "data") {
      if (data.unit.value == "GB") {
        postData["amount"] = data.value * 1024 * 1024 * 1024;
      }
      if (data.unit.value == "MB") {
        postData["amount"] = data.value * 1024 * 1024;
      }
      if (data.unit.value == "KB") {
        postData["amount"] = data.value * 1024;
      }
    }
    // voice and video
    let inisdeHours = data.hours;
    let insideMinutes = data.minutes;
    if (balance.type == "voice" || balance.type == "video") {
      if (data.hours.length === 0) {
        inisdeHours = 0;
      }
      if (data.minutes.length === 0) {
        insideMinutes = 0;
      }
      if (parseFloat(inisdeHours) == 0 && parseFloat(insideMinutes) == 0) {
        toast.error("Please enter hours or minutes");
      } else if (parseFloat(insideMinutes) > 59) {
        toast.error("Minutes can't be more than 59");
      } else {
        postData["amount"] = inisdeHours * 60 * 60 + insideMinutes * 60;
      }
    }
    // monetary
    if (balance.type == "monetary") {
      if (data.length === 0) {
        toast.error("Please enter amount");
      } else {
        postData["amount"] = parseFloat(data);
      }
    }
    if (postData.amount) {
      try {
        setAccountLoadings({ ...accountLoadings, debitBalance: true });
        const response = await httpService.patch(
          `/v1/accountbalances/debit`,
          postData
        );
        setAccountLoadings({ ...accountLoadings, debitBalance: false });
        if (response.status == 200 || response.status == 201) {
          toast.success("Balance debited successfully.");
          dispatch(setDebitModal(null));
          getAccountById(viewAccountData?.IMSI);
        }
      } catch ({ err, response }) {
        setAccountLoadings({ ...accountLoadings, debitBalance: false });
      }
    }
  };

  const exports = {
    getAccounts,
    getAccountById,
    deleteAccount,
    accountList,
    createAccountController,
    patchAccount,
    filters,
    setFilters,
    accountPaginates,
    setAccountPaginates,
    accountLoadings,
    getBalances,
    balanceList,
    selectedBalance,
    setSelectedBalance,
    addBalance,
    selectedAccountBalance,
    setSelectedAccountBalance,
    removeBalance,
    getAccountUsageHourly,
    getAccountUsageDaily,
    accountUsageData,
    updateBalance,
    topupBalance,
    debitBalance,
  };
  return exports;
};
export default useAccount;
