import { Fragment } from "react";
import Breadcrumbs from "@components/breadcrumbs";
import {
  Card,
  CardFooter,
  Button,
  CardBody,
  Row,
  Col,
  Label,
  Input,
  FormFeedback,
} from "reactstrap";
import useAccount from "../../../hooks/use_account";

const CreateAccount = () => {
  const { createAccountController, accountLoadings } = useAccount();

  return (
    <Fragment>
      <Breadcrumbs
        title="Create Account"
        data={[{ title: "Accounts" }, { title: "Create Account" }]}
      />
      <form onSubmit={createAccountController.handleSubmit}>
        <Card>
          <CardBody>
            <Row>
              <Col className="mb-1" xs="12" sm="6" md="6">
                <Label for="imsi">imsi</Label>
                <Input
                  value={createAccountController.values.imsi}
                  onChange={createAccountController.handleChange}
                  invalid={
                    createAccountController.touched.imsi
                      ? createAccountController.errors.imsi
                      : null
                  }
                  name="imsi"
                  id="imsi"
                />
                {createAccountController?.errors?.imsi && (
                  <FormFeedback>
                    {createAccountController.errors.imsi}
                  </FormFeedback>
                )}
              </Col>
              <Col className="mb-1" xs="12" sm="6" md="6">
                <Label for="msisdn">msisdn</Label>
                <Input
                  value={createAccountController.values.msisdn}
                  onChange={createAccountController.handleChange}
                  invalid={
                    createAccountController.touched.msisdn
                      ? createAccountController.errors.msisdn
                      : null
                  }
                  name="msisdn"
                  id="msisdn"
                />
                {createAccountController?.errors?.msisdn && (
                  <FormFeedback>
                    {createAccountController.errors.msisdn}
                  </FormFeedback>
                )}
              </Col>
              <Col xs="12" sm="6" md="2" className={"mb-1 mt-2"}>
                <div className="form-switch ps-0">
                  <div className="d-flex">
                    <p
                      className="fw-bold me-auto mb-0"
                      style={{ fontSize: 13 }}
                    >
                      permanent
                    </p>
                    <Input
                      value={createAccountController.values.permanent}
                      onChange={(e) => {
                        createAccountController.setFieldValue(
                          "permanent",
                          e.target.checked
                        );
                      }}
                      type="switch"
                    />
                  </div>
                </div>
              </Col>
            </Row>
          </CardBody>
          <CardFooter className="d-flex justify-content-center">
            <Button
              size="md"
              disabled={accountLoadings.createAccount}
              color={accountLoadings.createAccount ? "secondary" : "primary"}
            >
              Submit
            </Button>
          </CardFooter>
        </Card>
      </form>
    </Fragment>
  );
};
export default CreateAccount;
